    //                    cur(x-1,y) + cur(x+1,y) +
    //                    cur(x,y+1) + cur(x,y-1));
    Func jacobi("jacobi");
    jacobi(x, y) = w * (cur_param(x, y) +
                        cur_param(x - 1, y) +
                        cur_param(x + 1, y) +
                        cur_param(x, y + 1) +
                        cur_param(x, y - 1));

    // ------------------------------------------------------------------
    // Optimized schedule for the Jacobi step.
    //
    // Key goals:
    //  - Vectorize along x (columns), which are contiguous in memory.
    //  - Tile x and y to improve cache locality.
    //  - Parallelize across tiles in y to use many cores.
    //
    // We only ever realize this Func over the interior region [1..n-2]^2,
    // but the schedule is written generically, independent of n.
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tunable tile sizes (chosen conservatively for typical cache sizes).
    const int tile_x = 64;  // columns per tile
    const int tile_y = 32;  // rows per tile

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    jacobi
        .compute_root()                                      // explicit: single-stage pipeline
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)          // 2D tiling for better locality
        .vectorize(xi, vec_width)                            // SIMD across contiguous x
        .parallel(yo);                                       // parallelize over tile-rows

    // We will only apply the stencil to the interior points:
    // i,j = 1 .. n-2. The boundaries remain unchanged across time steps,
    // matching the original C code.
    //
    // Create interior views of A and B that alias the underlying storage.
    // Dimension 0 is x (j), dimension 1 is y (i).
    Halide::Buffer<num_t, 2> A_interior =
        A.cropped(0, 1, n - 2).cropped(1, 1, n - 2);
    Halide::Buffer<num_t, 2> B_interior =
        B.cropped(0, 1, n - 2).cropped(1, 1, n - 2);

    // Bind some initial buffer (say A) before compiling, so the JIT
    // can infer shapes for bounds analysis.
    cur_param.set(A);

    // Compile the Jacobi step once; we'll reuse it for all time steps.
    jacobi.compile_jit(target);

    // -------------------------------
    // Time-stepping loop, driven from the host
    // -------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Original C kernel:
    //
