    //       A[i][j] = stencil(B,...);
    // }
    //
    // We implement the same ping-pong using a single Halide Func "jacobi":
    for (int t = 0; t < tsteps; t++) {
        // First phase: B <- stencil(A)
        cur_param.set(A);
        jacobi.realize(B_interior);

        // Second phase: A <- stencil(B)
        cur_param.set(B);
        jacobi.realize(A_interior);
    }

